declare namespace SigApi {
    interface Color {
        /**
         * Returns the name of the color
         * 
         * @returns {string} The name of the color
         */
        getName(): string
        /**
         * Returns the alpha/transparency part of the color
         * 
         * @returns {number} The alpha value (between 0 and 255)
         */
        getAlpha(): number
        /**
         * Returns the red part of the color
         * 
         * @returns {number} The value of the red channel (between 0 and 255)
         */
        getRed(): number
        /**
        * Returns the green part of the color
        * 
        * @returns {number} The value of the green channel (between 0 and 255)
        */
        getGreen(): number
        /**
        * Returns the blue part of the color
        * 
        * @returns {number} The value of the blue channel (between 0 and 255)
        */
        getBlue(): number
        /**
         * Returns the Color represented as 32-bit integer
         * [8 bits] alpha <- MSB
         * [8 bits] red
         * [8 bits] green
         * [8 bits] blue  <- LSB
         * 
         * @returns {number} the color as integer
         */
        getColor(): number
        /**
         * Returns the color as rgba string
         * 
         * @returns {string} the color as rgba sting (e.g. 'rgba(50, 200, 110, 0.7)')
         */
        getColorRGBA(): string
        /**
         * Returns the color as hash string (the alpha value is ignored)
         * 
         * @returns {string} the color as hash string (e.g. '#1F5DE3')
         */
        getColorHash(): string
    }
}
